from pytest_bdd import then, parsers, scenarios
from playwright.sync_api import Page

scenarios("../../TC_001_shopping_list.feature")


# ── Steps unique to this TC ────────────────────────────────────────────────

@then(parsers.parse('I verify "{text}" is visible in the first item name'))
def i_verify_value_is_visible_in_the_first_item_name(page: Page, text: str):
    page.get_by_text(text, exact=False).first.scroll_into_view_if_needed()
    page.get_by_text(text, exact=False).first.wait_for(state="visible", timeout=15000)
